import { Order } from './types';

function compare(aDate: string, aId: string, bDate: string, bId: string): number {
  return aDate < bDate ? -1 : aDate > bDate ? 1 : aId < bId ? -1 : aId > bId ? 1 : 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  list(tenant: string): Order[] {
    return this.rows.filter(row => row.tenant === tenant).sort((a, b) =>
      compare(a.createdAt, a.id, b.createdAt, b.id));
  }

  /**
   * Orders of `tenant` strictly after the (createdAt, id) pair `after`, in
   * ascending (createdAt, id) order. The tenant filter is applied first; the
   * pair need not belong to an existing row or to this tenant.
   */
  listAfter(tenant: string, after?: { createdAt: string; id: string }): Order[] {
    const all = this.list(tenant);
    if (!after) return all;
    return all.filter(row => compare(row.createdAt, row.id, after.createdAt, after.id) > 0);
  }
}
